pub struct ObfuscatedTO {
    id: String,
    plain: BTreeMap<String, String>,
    #[serde(skip)] protected: Zeroizing<BTreeMap<String, String>>,
    sealed: Option<Vec<u8>>,                   // AEAD output: nonce || ciphertext || tag
}

impl Serialize for ObfuscatedTO {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        let mut st = s.serialize_struct("ObfuscatedTO", 2)?;
        st.serialize_field("sealed", &self.sealed)?;   // protected values never raw
        st.end()
    }
}
